import java.util.*;
public class EmployeeHashMap { public static void main(String[] a){Scanner s=new Scanner(System.in);HashMap<String,Double> e=new HashMap<>();System.out.print("Employees: ");int n=s.nextInt();s.nextLine();for(int i=0;i<n;i++){System.out.print("Name: ");String name=s.nextLine();System.out.print("Salary: ");e.put(name,s.nextDouble());s.nextLine();}for(Map.Entry<String,Double>x:e.entrySet())System.out.println(x.getKey()+" - "+x.getValue());System.out.print("Search name: ");String q=s.nextLine();if(e.containsKey(q))System.out.println(q+" salary: "+e.get(q));else System.out.println("Employee not found");s.close();} }
